"""One reviewed catalog -> language bindings. --check verifies exact generated bytes."""
import json, re, sys, math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'effects/presets.json').read_text())
def snake(k):return re.sub(r'([A-Z])',lambda m:'_'+m[1].lower(),k)
def rust(v,typ='f32'):
    if isinstance(v,bool):return str(v).lower()
    if isinstance(v,list):return '['+', '.join(rust(x,typ) for x in v)+']'
    if typ=='u32':return str(int(v))
    return repr(float(v))+typ

def fields(d,ints=()):return ', '.join(f'{snake(k)}: {rust(v,"u32" if k in ints else "f32")}' for k,v in d.items())

def generate():
    ids=set(); keys=set(); arms=[]
    for p in DATA['presets']:
        assert p['id'] not in ids and p['key'] not in keys;ids.add(p['id']);keys.add(p['key'])
        c=p['config'].copy();boundary=c.pop('boundary');e=p['emitter'];m=p['material'];proc=p['procedural'];profile=p['profile'];kind={'fluid':0,'cloud':1,'fog':2}[p['kind']]
        assert all(n%2==0 for n in c['cells']) and all(4<=n/2<=n*2<=192 for n in c['cells'])
        assert math.prod(n*2+1 for n in c['cells'])<=2097152
        ps='None' if not proc else 'Some(ProceduralSettings { '+fields(proc,('seed',))+' })'
        points='&[]' if not profile else '&'+rust(profile['points'],'f64')
        arms.append(f'''        {p['id']} => Preset {{ id: {p['id']}, key: "{p['key']}", kind: {kind},
            config: Config {{ {fields(c,('cells','maxSubsteps','pressureIterations'))}, boundary: Boundary::{['Open','Closed'][boundary]} }},
            emitter: Emitter {{ {fields(e)} }},
            material: Material {{ {fields(m)} }}, procedural: {ps},
            profile: {points}, duration: {rust(profile['duration'] if profile else 0,'f64')}, ember: {str(p['ember']).lower()} }},''')
    qarms=[]
    for i,q in enumerate(DATA['quality'].values()):
        qarms.append(f'        {i} => ({rust(q["scale"])}, {q["pressureIterations"]}, {q["steps"]}, {q["uploadHz"]}, {q["proceduralUploadHz"]}),')
    rs='// Generated by tools/generate_effects.py; edit effects/presets.json.\nuse super::*;\n\npub(super) fn base(id: u32) -> Option<Preset> {\n    Some(match id {\n'+'\n'.join(arms)+'\n        _ => return None,\n    })\n}\n\npub(super) fn quality(id: u32) -> Option<(f32,u32,u32,u32,u32)> {\n    Some(match id {\n'+'\n'.join(qarms)+'\n        _ => return None,\n    })\n}\n'
    return {ROOT/'crates/vapor-core/src/effects/generated.rs':rs,ROOT/'bindings/web/effect-catalog.mjs':'// Generated; do not edit.\nexport default '+json.dumps(DATA,separators=(',',':'))+';\n',ROOT/'bindings/python/vapor_game/presets.json':(ROOT/'effects/presets.json').read_text()}
for path,contents in generate().items():
    if '--check' in sys.argv:
        if not path.exists() or path.read_text()!=contents:raise SystemExit(f'Stale catalog: {path}')
    else:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(contents)
print('PASS effect catalog synchronization')
